import { ARMOR_PIECES, type BlockSpec, type ElementSpec, type ItemSpec, type MobSpec, type OreSpec, type Project, type ToolSpec } from "../../schema.js";
import { resolveRef } from "./refs.js";

export const GENERATED_HEADER =
  "// Generated by Mod Creator from spec/. Do not edit: this file is rewritten on every generate.\n" +
  "// Put hand-written code in src/main/java instead.";

/** `ruby_ore` -> `RUBY_ORE` */
export const constName = (id: string) => id.toUpperCase();

/** `ruby_ore` -> `RubyOre` */
export const pascal = (id: string) =>
  id.split(/[_-]/).filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join("");

const float = (n: number) => (Number.isInteger(n) ? `${n}.0f` : `${n}f`);
const double = (n: number) => (Number.isInteger(n) ? `${n}.0` : `${n}`);

/** Java expression for an item: a ModContent field for our own ids, a registry lookup for anything else. */
function itemExpr(modId: string, ref: string): string {
  const full = resolveRef(modId, ref);
  if (full.startsWith(`${modId}:`)) return `ModContent.${constName(full.slice(modId.length + 1))}`;
  return `BuiltInRegistries.ITEM.getValue(Identifier.parse("${full}"))`;
}

/** Java expression for `stack` matching an item id or `#tag`. */
function stackTest(modId: string, ref: string): string {
  if (ref.startsWith("#")) return `stack.is(TagKey.create(Registries.ITEM, Identifier.parse("${resolveRef(modId, ref).slice(1)}")))`;
  return `stack.is(${itemExpr(modId, ref)})`;
}

function blockProperties(spec: BlockSpec): string {
  const b = spec.block;
  let props = "BlockBehaviour.Properties.of()";
  props += `\n\t\t\t.strength(${float(b.hardness)}, ${float(b.resistance)})`;
  props += `\n\t\t\t.sound(SoundType.${b.sound.toUpperCase()})`;
  if (b.requiresTool) props += "\n\t\t\t.requiresCorrectToolForDrops()";
  if (b.lightLevel > 0) props += `\n\t\t\t.lightLevel(state -> ${b.lightLevel})`;
  return props;
}

function rarity(r: string): string {
  return r !== "common" ? `.rarity(Rarity.${r.toUpperCase()})` : "";
}

function itemProperties(spec: ItemSpec): string {
  let props = "new Item.Properties()";
  if (spec.item.maxStackSize !== 64) props += `.stacksTo(${spec.item.maxStackSize})`;
  props += rarity(spec.item.rarity);
  const food = spec.item.food;
  if (food) {
    props += `\n\t\t\t.food(new FoodProperties.Builder().nutrition(${food.nutrition}).saturationModifier(${float(food.saturation)})`;
    props += food.alwaysEdible ? ".alwaysEdible().build())" : ".build())";
  }
  return props;
}

const TIER_TAGS: Record<ToolSpec["tool"]["tier"], string> = {
  wood: "INCORRECT_FOR_WOODEN_TOOL",
  stone: "INCORRECT_FOR_STONE_TOOL",
  copper: "INCORRECT_FOR_COPPER_TOOL",
  iron: "INCORRECT_FOR_IRON_TOOL",
  gold: "INCORRECT_FOR_GOLD_TOOL",
  diamond: "INCORRECT_FOR_DIAMOND_TOOL",
  netherite: "INCORRECT_FOR_NETHERITE_TOOL",
};

/** Item tag holding a tool's or armor set's repair item; written by the resource generator. */
export const repairTag = (id: string) => `${id}_repair_items`;

/** Default sounds for mobs that borrow a vanilla body. */
const MOB_SOUNDS: Record<MobSpec["mob"]["model"], { ambient: string; hurt: string; death: string }> = {
  pig: { ambient: "minecraft:entity.pig.ambient", hurt: "minecraft:entity.pig.hurt", death: "minecraft:entity.pig.death" },
  cow: { ambient: "minecraft:entity.cow.ambient", hurt: "minecraft:entity.cow.hurt", death: "minecraft:entity.cow.death" },
};

const MOB_MODELS: Record<MobSpec["mob"]["model"], { model: string; baby: string; layer: string; shadow: number; pkg: string }> = {
  pig: { model: "PigModel", baby: "BabyPigModel", layer: "PIG", shadow: 0.7, pkg: "net.minecraft.client.model.animal.pig" },
  cow: { model: "CowModel", baby: "BabyCowModel", layer: "COW", shadow: 0.7, pkg: "net.minecraft.client.model.animal.cow" },
};

const tab = (t: string) => `CreativeModeTabs.${t.toUpperCase()}`;

/** The generated `ModContent` class: registers every element, fills creative tabs and hooks into worldgen. */
export function modContentJava(project: Project, elements: ElementSpec[]): string {
  const modId = project.modId;
  const pkg = `${project.package}.generated`;
  const of = <K extends ElementSpec["kind"]>(kind: K) => elements.filter((e): e is Extract<ElementSpec, { kind: K }> => e.kind === kind);
  const blocks = of("block");
  const items = of("item");
  const tools = of("tool");
  const armors = of("armor");
  const trees = of("tree");
  const plants = of("plant");
  const mobs = of("mob");
  const ores = of("ore");

  const imports = new Set<string>([
    "java.util.function.Function",
    "net.fabricmc.fabric.api.creativetab.v1.CreativeModeTabEvents",
    "net.minecraft.core.Registry",
    "net.minecraft.core.registries.BuiltInRegistries",
    "net.minecraft.core.registries.Registries",
    "net.minecraft.resources.Identifier",
    "net.minecraft.resources.ResourceKey",
    "net.minecraft.world.item.BlockItem",
    "net.minecraft.world.item.CreativeModeTabs",
    "net.minecraft.world.item.Item",
    "net.minecraft.world.item.Rarity",
    "net.minecraft.world.level.block.Block",
    "net.minecraft.world.level.block.SoundType",
    "net.minecraft.world.level.block.state.BlockBehaviour",
  ]);
  const use = (...names: string[]) => names.forEach((n) => imports.add(n));

  const materials: string[] = [];
  const fields: string[] = [];
  const body: string[] = [];
  /** Creative tab entries grouped by tab, in spec order. */
  const tabs = new Map<string, string[]>();
  const addToTab = (t: string | undefined, ref: string) => t && tabs.set(t, [...(tabs.get(t) ?? []), ref]);

  for (const b of blocks) {
    const factory = b.customClass ? `${b.customClass}::new` : "Block::new";
    fields.push(
      `\t/** ${b.name} (spec/blocks/${b.id}.json) */\n` +
        `\tpublic static final Block ${constName(b.id)} = registerBlock("${b.id}", ${factory},\n\t\t\t${blockProperties(b)}, ${b.hasItem});`,
    );
    if (b.hasItem) addToTab(b.creativeTab, `${constName(b.id)}.asItem()`);
  }

  for (const t of trees) {
    use(
      "net.minecraft.world.level.block.Blocks",
      "net.minecraft.world.level.block.RotatedPillarBlock",
      "net.minecraft.world.level.block.SaplingBlock",
      "net.minecraft.world.level.block.TintedParticleLeavesBlock",
      "net.minecraft.world.level.block.grower.TreeGrower",
      "net.minecraft.util.random.WeightedList",
      "net.fabricmc.fabric.api.registry.FlammableBlockRegistry",
    );
    const C = constName(t.id);
    const feature = `ResourceKey.create(Registries.FEATURE, id("${t.id}"))`;
    fields.push(
      `\t// ${t.name} wood (spec/trees/${t.id}.json)\n` +
        `\tprivate static final TreeGrower ${C}_GROWER = new TreeGrower("${modId}:${t.id}",\n` +
        `\t\t\tWeightedList.of(${feature}), WeightedList.of(), WeightedList.of(), ${feature});\n` +
        `\tpublic static final Block ${C}_LOG = registerBlock("${t.id}_log", RotatedPillarBlock::new,\n\t\t\tBlockBehaviour.Properties.ofFullCopy(Blocks.OAK_LOG), true);\n` +
        `\tpublic static final Block ${C}_PLANKS = registerBlock("${t.id}_planks", Block::new,\n\t\t\tBlockBehaviour.Properties.ofFullCopy(Blocks.OAK_PLANKS), true);\n` +
        `\tpublic static final Block ${C}_LEAVES = registerBlock("${t.id}_leaves", properties -> new TintedParticleLeavesBlock(0.01f, properties),\n\t\t\tBlockBehaviour.Properties.ofFullCopy(Blocks.OAK_LEAVES), true);\n` +
        `\tpublic static final Block ${C}_SAPLING = registerBlock("${t.id}_sapling", properties -> new SaplingBlock(${C}_GROWER, properties),\n\t\t\tBlockBehaviour.Properties.ofFullCopy(Blocks.OAK_SAPLING), true);`,
    );
    for (const part of ["LOG", "PLANKS", "LEAVES", "SAPLING"]) addToTab(t.creativeTab, `${C}_${part}.asItem()`);
    body.push(
      `\t\t// ${t.name} wood burns like oak.\n` +
        `\t\tFlammableBlockRegistry.getDefaultInstance().add(${C}_LOG, 5, 5);\n` +
        `\t\tFlammableBlockRegistry.getDefaultInstance().add(${C}_PLANKS, 5, 20);\n` +
        `\t\tFlammableBlockRegistry.getDefaultInstance().add(${C}_LEAVES, 30, 60);`,
    );
  }

  for (const p of plants) {
    use("net.minecraft.world.level.block.Blocks", "net.minecraft.world.level.block.BushBlock");
    const factory = p.customClass ? `${p.customClass}::new` : "BushBlock::new";
    let props = "BlockBehaviour.Properties.ofFullCopy(Blocks.SHORT_GRASS)";
    if (!p.plant.offset) props += ".offsetType(BlockBehaviour.OffsetType.NONE)";
    fields.push(
      `\t/** ${p.name} (spec/plants/${p.id}.json) */\n` +
        `\tpublic static final Block ${constName(p.id)} = registerBlock("${p.id}", ${factory},\n\t\t\t${props}, true);`,
    );
    addToTab(p.creativeTab, `${constName(p.id)}.asItem()`);
  }

  for (const i of items) {
    if (i.item.food) use("net.minecraft.world.food.FoodProperties");
    const factory = i.customClass ? `${i.customClass}::new` : "Item::new";
    fields.push(
      `\t/** ${i.name} (spec/items/${i.id}.json) */\n` +
        `\tpublic static final Item ${constName(i.id)} = registerItem("${i.id}", ${factory}, ${itemProperties(i)});`,
    );
    addToTab(i.creativeTab, constName(i.id));
  }

  for (const t of tools) {
    use("net.minecraft.world.item.ToolMaterial", "net.minecraft.tags.BlockTags", "net.minecraft.tags.TagKey");
    const C = constName(t.id);
    const x = t.tool;
    materials.push(
      `\tprivate static final ToolMaterial ${C}_MATERIAL = new ToolMaterial(BlockTags.${TIER_TAGS[x.tier]},\n` +
        `\t\t\t${x.durability}, ${float(x.miningSpeed)}, 0.0f, ${x.enchantability}, TagKey.create(Registries.ITEM, id("${repairTag(t.id)}")));`,
    );
    const factory = t.customClass ? `${t.customClass}::new` : "Item::new";
    fields.push(
      `\t/** ${t.name} (spec/tools/${t.id}.json) */\n` +
        `\tpublic static final Item ${C} = registerItem("${t.id}", ${factory},\n` +
        `\t\t\tnew Item.Properties().${x.type}(${C}_MATERIAL, ${float(x.attackDamage)}, ${float(x.attackSpeed)})${rarity(x.rarity)});`,
    );
    addToTab(t.creativeTab, C);
  }

  for (const a of armors) {
    use(
      "java.util.Map",
      "net.minecraft.sounds.SoundEvents",
      "net.minecraft.tags.TagKey",
      "net.minecraft.world.item.equipment.ArmorMaterial",
      "net.minecraft.world.item.equipment.ArmorType",
      "net.minecraft.world.item.equipment.EquipmentAssets",
    );
    const C = constName(a.id);
    const x = a.armor;
    const d = x.defense;
    materials.push(
      `\tprivate static final ArmorMaterial ${C}_MATERIAL = new ArmorMaterial(${x.durability},\n` +
        `\t\t\tMap.of(ArmorType.HELMET, ${d.helmet}, ArmorType.CHESTPLATE, ${d.chestplate}, ArmorType.LEGGINGS, ${d.leggings}, ArmorType.BOOTS, ${d.boots}, ArmorType.BODY, ${d.chestplate}),\n` +
        `\t\t\t${x.enchantability}, SoundEvents.ARMOR_EQUIP_${x.equipSound.toUpperCase()}, ${float(x.toughness)}, ${float(x.knockbackResistance)},\n` +
        `\t\t\tTagKey.create(Registries.ITEM, id("${repairTag(a.id)}")),\n` +
        `\t\t\tResourceKey.create(EquipmentAssets.ROOT_ID, id("${a.id}")));`,
    );
    for (const piece of ARMOR_PIECES) {
      if (!x.pieces[piece]) continue;
      const pid = `${a.id}_${piece}`;
      fields.push(
        `\t/** ${a.name} ${piece} (spec/armor/${a.id}.json) */\n` +
          `\tpublic static final Item ${constName(pid)} = registerItem("${pid}", Item::new,\n` +
          `\t\t\tnew Item.Properties().humanoidArmor(${C}_MATERIAL, ArmorType.${piece.toUpperCase()})${rarity(x.rarity)});`,
      );
      addToTab(a.creativeTab, constName(pid));
    }
  }

  for (const m of mobs) {
    use(
      "net.minecraft.world.entity.EntityType",
      "net.minecraft.world.entity.Entity",
      "net.minecraft.world.entity.MobCategory",
      "net.minecraft.world.entity.SpawnPlacements",
      "net.minecraft.world.entity.SpawnPlacementTypes",
      "net.minecraft.world.entity.animal.Animal",
      "net.minecraft.world.entity.ai.attributes.Attributes",
      "net.minecraft.world.item.SpawnEggItem",
      "net.minecraft.world.level.levelgen.Heightmap",
      "net.fabricmc.fabric.api.object.builder.v1.entity.FabricDefaultAttributeRegistry",
      `${pkg}.entity.${pascal(m.id)}`,
    );
    const C = constName(m.id);
    const P = pascal(m.id);
    fields.push(
      `\t/** ${m.name} (spec/mobs/${m.id}.json) */\n` +
        `\tpublic static final EntityType<${P}> ${C} = registerEntity("${m.id}",\n` +
        `\t\t\tEntityType.Builder.of(${P}::new, MobCategory.CREATURE).sized(${float(m.mob.width)}, ${float(m.mob.height)}));\n` +
        `\tpublic static final Item ${C}_SPAWN_EGG = registerItem("${m.id}_spawn_egg", SpawnEggItem::new, new Item.Properties().spawnEgg(${C}));`,
    );
    addToTab("spawn_eggs", `${C}_SPAWN_EGG`);
    body.push(
      `\t\t// ${m.name} (spec/mobs/${m.id}.json)\n` +
        `\t\tFabricDefaultAttributeRegistry.register(${C}, Animal.createAnimalAttributes()\n` +
        `\t\t\t\t.add(Attributes.MAX_HEALTH, ${double(m.mob.health)})\n` +
        `\t\t\t\t.add(Attributes.MOVEMENT_SPEED, ${double(m.mob.speed)}));\n` +
        `\t\tSpawnPlacements.register(${C}, SpawnPlacementTypes.ON_GROUND, Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, Animal::checkAnimalSpawnRules);`,
    );
  }

  const tabCode = [...tabs].map(
    ([t, refs]) =>
      `\t\tCreativeModeTabEvents.modifyOutputEvent(${tab(t)}).register(output -> {\n` +
      refs.map((r) => `\t\t\toutput.accept(${r});`).join("\n") +
      "\n\t\t});",
  );

  const SELECTORS: Record<OreSpec["ore"]["replaces"], string> = {
    stone: "foundInOverworld",
    deepslate: "foundInOverworld",
    stone_and_deepslate: "foundInOverworld",
    netherrack: "foundInTheNether",
    end_stone: "foundInTheEnd",
  };
  if (ores.length) {
    use(
      "net.fabricmc.fabric.api.biome.v1.BiomeModifications",
      "net.fabricmc.fabric.api.biome.v1.BiomeSelectors",
      "net.minecraft.world.level.levelgen.GenerationStep",
    );
  }
  const oreCode = ores.map(
    (o) =>
      `\t\t// ${o.name} (spec/worldgen/${o.id}.json)\n` +
      `\t\tBiomeModifications.addFeature(BiomeSelectors.${SELECTORS[o.ore.replaces]}(), GenerationStep.Decoration.UNDERGROUND_ORES,\n` +
      `\t\t\t\tResourceKey.create(Registries.PLACED_FEATURE, id("${o.id}")));`,
  );
  const registerBody = [...tabCode, ...body, ...oreCode];

  const entityHelper = mobs.length
    ? `

\tprivate static <T extends Entity> EntityType<T> registerEntity(String name, EntityType.Builder<T> builder) {
\t\tResourceKey<EntityType<?>> key = ResourceKey.create(Registries.ENTITY_TYPE, id(name));
\t\treturn Registry.register(BuiltInRegistries.ENTITY_TYPE, key, builder.build(key));
\t}`
    : "";

  return `${GENERATED_HEADER}
package ${pkg};

${sortImports(imports)}

public final class ModContent {
\tpublic static final String MOD_ID = "${modId}";
${materials.length ? `\n${materials.join("\n")}\n` : ""}
${fields.join("\n\n")}

\tprivate ModContent() {
\t}

\t/** Call once from your mod initializer. Loading this class registers everything above. */
\tpublic static void register() {
${registerBody.join("\n") || "\t\t// Nothing else to register."}
\t}

\tprivate static Block registerBlock(String name, Function<BlockBehaviour.Properties, Block> factory,
\t\t\tBlockBehaviour.Properties properties, boolean withItem) {
\t\tResourceKey<Block> blockKey = ResourceKey.create(Registries.BLOCK, id(name));
\t\tBlock block = factory.apply(properties.setId(blockKey));
\t\tif (withItem) {
\t\t\tResourceKey<Item> itemKey = ResourceKey.create(Registries.ITEM, id(name));
\t\t\tRegistry.register(BuiltInRegistries.ITEM, itemKey,
\t\t\t\t\tnew BlockItem(block, new Item.Properties().setId(itemKey).useBlockDescriptionPrefix()));
\t\t}
\t\treturn Registry.register(BuiltInRegistries.BLOCK, blockKey, block);
\t}

\tprivate static Item registerItem(String name, Function<Item.Properties, Item> factory, Item.Properties properties) {
\t\tResourceKey<Item> key = ResourceKey.create(Registries.ITEM, id(name));
\t\treturn Registry.register(BuiltInRegistries.ITEM, key, factory.apply(properties.setId(key)));
\t}${entityHelper}

\tstatic Identifier id(String path) {
\t\treturn Identifier.fromNamespaceAndPath(MOD_ID, path);
\t}
}
`;
}

/** `java.*` first, then the rest, each group sorted, like IntelliJ's default. */
function sortImports(imports: Set<string>): string {
  const all = [...imports].sort();
  const java = all.filter((i) => i.startsWith("java."));
  const rest = all.filter((i) => !i.startsWith("java."));
  return [java, rest]
    .filter((g) => g.length)
    .map((g) => g.map((i) => `import ${i};`).join("\n"))
    .join("\n\n");
}

/** One class per mob: a vanilla-style animal that wanders, panics, follows its food and breeds. */
export function mobEntityJava(project: Project, m: MobSpec): string {
  const modId = project.modId;
  const P = pascal(m.id);
  const sounds = { ...MOB_SOUNDS[m.mob.model], ...m.mob.sounds };
  const sound = (ref: string) => `BuiltInRegistries.SOUND_EVENT.getValue(Identifier.parse("${resolveRef("minecraft", ref)}"))`;
  const test = stackTest(modId, m.mob.food);
  const tagImports = test.includes("TagKey") ? "import net.minecraft.core.registries.Registries;\n" : "";
  return `${GENERATED_HEADER}
package ${project.package}.generated.entity;

import net.minecraft.core.registries.BuiltInRegistries;
${tagImports}import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvent;
${test.includes("TagKey") ? "import net.minecraft.tags.TagKey;\n" : ""}import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.AgeableMob;
import net.minecraft.world.entity.EntitySpawnReason;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.ai.goal.BreedGoal;
import net.minecraft.world.entity.ai.goal.FloatGoal;
import net.minecraft.world.entity.ai.goal.FollowParentGoal;
import net.minecraft.world.entity.ai.goal.LookAtPlayerGoal;
import net.minecraft.world.entity.ai.goal.PanicGoal;
import net.minecraft.world.entity.ai.goal.RandomLookAroundGoal;
import net.minecraft.world.entity.ai.goal.TemptGoal;
import net.minecraft.world.entity.ai.goal.WaterAvoidingRandomStrollGoal;
import net.minecraft.world.entity.animal.Animal;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;

import ${project.package}.generated.ModContent;

/** ${m.name} (spec/mobs/${m.id}.json). For custom behavior, subclass it in src/main/java. */
public class ${P} extends Animal {
\tpublic ${P}(EntityType<? extends ${P}> type, Level level) {
\t\tsuper(type, level);
\t}

\t@Override
\tprotected void registerGoals() {
\t\tthis.goalSelector.addGoal(0, new FloatGoal(this));
\t\tthis.goalSelector.addGoal(1, new PanicGoal(this, 1.25));
\t\tthis.goalSelector.addGoal(3, new BreedGoal(this, 1.0));
\t\tthis.goalSelector.addGoal(4, new TemptGoal(this, 1.2, this::isFood, false));
\t\tthis.goalSelector.addGoal(5, new FollowParentGoal(this, 1.1));
\t\tthis.goalSelector.addGoal(6, new WaterAvoidingRandomStrollGoal(this, 1.0));
\t\tthis.goalSelector.addGoal(7, new LookAtPlayerGoal(this, Player.class, 6.0f));
\t\tthis.goalSelector.addGoal(8, new RandomLookAroundGoal(this));
\t}

\t@Override
\tpublic boolean isFood(ItemStack stack) {
\t\treturn ${test};
\t}

\t@Override
\tpublic AgeableMob getBreedOffspring(ServerLevel level, AgeableMob partner) {
\t\treturn ModContent.${constName(m.id)}.create(level, EntitySpawnReason.BREEDING);
\t}

\t@Override
\tprotected SoundEvent getAmbientSound() {
\t\treturn ${sound(sounds.ambient)};
\t}

\t@Override
\tprotected SoundEvent getHurtSound(DamageSource source) {
\t\treturn ${sound(sounds.hurt)};
\t}

\t@Override
\tprotected SoundEvent getDeathSound() {
\t\treturn ${sound(sounds.death)};
\t}
}
`;
}

/** A renderer that draws the mob with a vanilla body and its own textures, switching to the baby body for babies. */
export function mobRendererJava(project: Project, m: MobSpec): string {
  const P = pascal(m.id);
  const model = MOB_MODELS[m.mob.model];
  const M = model.model;
  return `${GENERATED_HEADER}
package ${project.package}.generated.client;

import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.model.AdultAndBabyModelPair;
import net.minecraft.client.model.geom.ModelLayers;
import net.minecraft.client.renderer.SubmitNodeCollector;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;
import net.minecraft.client.renderer.state.level.CameraRenderState;
import net.minecraft.resources.Identifier;
import ${model.pkg}.${model.baby};
import ${model.pkg}.${M};

import ${project.package}.generated.ModContent;
import ${project.package}.generated.entity.${P};

/** Draws ${m.name} with the vanilla ${m.mob.model} body (spec/mobs/${m.id}.json). */
public class ${P}Renderer extends MobRenderer<${P}, LivingEntityRenderState, ${M}> {
\tprivate static final Identifier TEXTURE = Identifier.fromNamespaceAndPath(ModContent.MOD_ID, "textures/entity/${m.id}.png");
\tprivate static final Identifier BABY_TEXTURE = Identifier.fromNamespaceAndPath(ModContent.MOD_ID, "textures/entity/${m.id}_baby.png");

\tprivate final AdultAndBabyModelPair<${M}> models;

\tpublic ${P}Renderer(EntityRendererProvider.Context context) {
\t\tthis(context, new AdultAndBabyModelPair<>(new ${M}(context.bakeLayer(ModelLayers.${model.layer})),
\t\t\t\tnew ${model.baby}(context.bakeLayer(ModelLayers.${model.layer}_BABY))));
\t}

\tprivate ${P}Renderer(EntityRendererProvider.Context context, AdultAndBabyModelPair<${M}> models) {
\t\tsuper(context, models.adultModel(), ${float(model.shadow)});
\t\tthis.models = models;
\t}

\t@Override
\tpublic LivingEntityRenderState createRenderState() {
\t\treturn new LivingEntityRenderState();
\t}

\t@Override
\tpublic Identifier getTextureLocation(LivingEntityRenderState state) {
\t\treturn state.isBaby ? BABY_TEXTURE : TEXTURE;
\t}

\t@Override
\tpublic void submit(LivingEntityRenderState state, PoseStack poseStack, SubmitNodeCollector collector, CameraRenderState camera) {
\t\tthis.model = this.models.getModel(state.isBaby);
\t\tsuper.submit(state, poseStack, collector, camera);
\t}
}
`;
}

/** Client entrypoint: registers renderers. Listed in fabric.mod.json under "client". */
export function modContentClientJava(project: Project, elements: ElementSpec[]): string {
  const mobs = elements.filter((e): e is MobSpec => e.kind === "mob");
  const pkg = `${project.package}.generated`;
  const imports = mobs.length
    ? [
        "import net.minecraft.client.renderer.entity.EntityRenderers;",
        ...mobs.map((m) => `import ${pkg}.client.${pascal(m.id)}Renderer;`),
      ]
    : [];
  return `${GENERATED_HEADER}
package ${pkg};

import net.fabricmc.api.ClientModInitializer;
${imports.length ? "\n" + imports.join("\n") + "\n" : ""}
/** Client-side setup for generated content. fabric.mod.json lists this class as the "client" entrypoint. */
public final class ModContentClient implements ClientModInitializer {
\t@Override
\tpublic void onInitializeClient() {
${mobs.map((m) => `\t\tEntityRenderers.register(ModContent.${constName(m.id)}, ${pascal(m.id)}Renderer::new);`).join("\n") || "\t\t// Nothing to set up yet."}
\t}
}
`;
}

/** Java files besides ModContent, keyed by path relative to the generated package folder. */
export function extraJavaFiles(project: Project, elements: ElementSpec[]): Map<string, string> {
  const out = new Map<string, string>();
  out.set("ModContentClient.java", modContentClientJava(project, elements));
  for (const e of elements) {
    if (e.kind !== "mob") continue;
    out.set(`entity/${pascal(e.id)}.java`, mobEntityJava(project, e));
    out.set(`client/${pascal(e.id)}Renderer.java`, mobRendererJava(project, e));
  }
  return out;
}

/** A starter class for `customClass`, written to src/main/java once and never again. */
export function starterClassJava(fqcn: string, kind: "block" | "item" | "plant"): string {
  const dot = fqcn.lastIndexOf(".");
  const pkg = fqcn.slice(0, dot);
  const name = fqcn.slice(dot + 1);
  if (kind === "block" || kind === "plant") {
    const base = kind === "plant" ? "BushBlock" : "Block";
    return `package ${pkg};

import net.minecraft.world.level.block.${base};
import net.minecraft.world.level.block.state.BlockBehaviour;

/**
 * Custom behavior for a block managed by Mod Creator. This file is yours: the generator created it once
 * and will never change it. Override ${base} methods here.
 */
public class ${name} extends ${base} {
\tpublic ${name}(BlockBehaviour.Properties properties) {
\t\tsuper(properties);
\t}
}
`;
  }
  return `package ${pkg};

import net.minecraft.world.item.Item;

/**
 * Custom behavior for an item managed by Mod Creator. This file is yours: the generator created it once
 * and will never change it. Override Item methods here.
 */
public class ${name} extends Item {
\tpublic ${name}(Item.Properties properties) {
\t\tsuper(properties);
\t}
}
`;
}
